// BRAND SEEDS & SEASONAL KEYWORD BUILDER
// Max 10 unique keywords per run (SerpAPI free tier: 100/month, weekly runs)
const now = new Date();
const currentMonth = now.getMonth() + 1;
const nextMonth = currentMonth === 12 ? 1 : currentMonth + 1;
const runDate = now.toISOString().split('T')[0];

const brands = ['SparkVibe','VibeBloom','PulsePlay','ScribbleSpark','PawPop','GlowGiggle','TinyGiggle'];

const seasonalByMonth = {
  1: [{event:'New Year',kw:'new year graphic tee'},{event:'MLK Day',kw:'mlk day shirt'}],
  2: [{event:"Valentine's Day",kw:'valentines day funny shirt'},{event:'Super Bowl',kw:'super bowl shirt funny'}],
  3: [{event:"St. Patrick's Day",kw:'st patricks day shirt'},{event:"Women's Day",kw:'womens day gift shirt'}],
  4: [{event:'Easter',kw:'easter graphic tee'},{event:'Earth Day',kw:'earth day apparel'}],
  5: [{event:"Mother's Day",kw:'mothers day gift shirt'},{event:'Mental Health Month',kw:'mental health awareness shirt'}],
  6: [{event:"Father's Day",kw:'fathers day gift shirt'},{event:'Pride Month',kw:'pride month apparel'}],
  7: [{event:'Independence Day',kw:'4th of july shirt'},{event:'Summer',kw:'summer graphic tee'}],
  8: [{event:'Back to School',kw:'back to school shirt funny'},{event:'National Dog Day',kw:'national dog day shirt'}],
  9: [{event:'Labor Day',kw:'labor day apparel'},{event:'Fall Season',kw:'fall season graphic tee'}],
  10:[{event:'Halloween',kw:'halloween funny shirt'},{event:'Breast Cancer Awareness',kw:'breast cancer awareness shirt'}],
  11:[{event:'Thanksgiving',kw:'thanksgiving funny shirt'},{event:'Veterans Day',kw:'veterans day apparel'}],
  12:[{event:'Christmas',kw:'christmas funny shirt'},{event:'Hanukkah',kw:'hanukkah gift shirt'}]
};

const evergreenByNiche = [
  {brand:'SparkVibe',  seeds:['funny sarcastic shirt','vintage aesthetic tee']},
  {brand:'VibeBloom',  seeds:['wildflower botanical print','wellness aesthetic shirt']},
  {brand:'PulsePlay',  seeds:['gym motivation shirt','fitness gift ideas']},
  {brand:'ScribbleSpark',seeds:['book lover gift shirt','writer aesthetic shirt']},
  {brand:'PawPop',     seeds:['dog mom shirt funny','cat dad gift shirt']},
  {brand:'GlowGiggle', seeds:['funny home decor gift','plant parent shirt']},
  {brand:'TinyGiggle', seeds:['funny toddler shirt','baby shower gift funny']}
];

const seen = new Set();
const items = [];

// Priority 1: seasonal (current + next month)
const seasonalEvents = [...(seasonalByMonth[currentMonth]||[]),...(seasonalByMonth[nextMonth]||[])];
for (const ev of seasonalEvents) {
  if (!seen.has(ev.kw)) {
    seen.add(ev.kw);
    items.push({json:{keyword:ev.kw,event_name:ev.event,type:'seasonal',applicable_brands:brands,run_date:runDate}});
  }
}

// Priority 2: one evergreen per brand (rotate weekly)
const weekNum = Math.floor((now - new Date(now.getFullYear(),0,1))/(7*864e5));
for (const b of evergreenByNiche) {
  const kw = b.seeds[weekNum % b.seeds.length];
  if (kw && !seen.has(kw)) {
    seen.add(kw);
    items.push({json:{keyword:kw,event_name:'',type:'evergreen',applicable_brands:[b.brand],run_date:runDate}});
  }
}

return items.slice(0, 10);

// Normalize SerpAPI results from all 3 horizons
const loopItem = $('Split: Loop Per Keyword').item.json;

function extractScore(apiResponse) {
  try {
    const avg = apiResponse?.interest_over_time?.averages;
    if (avg && avg.length > 0) return avg[0].value || 0;
    // fallback: last timeline point
    const timeline = apiResponse?.interest_over_time?.timeline_data;
    if (timeline && timeline.length > 0) {
      const last = timeline[timeline.length - 1];
      return last?.values?.[0]?.extracted_value || 0;
    }
    return 0;
  } catch(e) { return 0; }
}

function extractRising(apiResponse) {
  try {
    const rising = apiResponse?.related_queries?.rising || [];
    return rising.slice(0, 5).map(r => r.query).join(', ');
  } catch(e) { return ''; }
}

const data7d  = $('SerpAPI: Trending Now (7d)').item.json;
const data3m  = $('SerpAPI: 3 Months').item.json;
const data1yr = $('SerpAPI: 1 Year').item.json;

const score7d  = extractScore(data7d);
const score3m  = extractScore(data3m);
const score1yr = extractScore(data1yr);
const risingQueries = extractRising(data1yr) || extractRising(data3m) || extractRising(data7d);

return [{
  json: {
    ...loopItem,
    interest_score_7d: score7d,
    interest_score_3m: score3m,
    interest_score_1yr: score1yr,
    rising_queries: risingQueries
  }
}];

// Build Ollama scoring prompt with few-shot context from preference signals
const trendItem = $('Code: Normalize Results').item.json;

// Preference signals — may be empty if first run (handled gracefully)
let prefSignals = [];
try {
  const rawPrefs = $('Supabase: Get Preference Signals').item.json;
  prefSignals = Array.isArray(rawPrefs) ? rawPrefs : [];
} catch(e) { prefSignals = []; }

// Build few-shot examples from past decisions
const fewShot = prefSignals.length > 0
  ? prefSignals.map(p =>
      `${p.signal_type.toUpperCase()}: brand=${p.brand}, niche="${p.niche_keyword}" ${p.content ? '→ "' + p.content + '"' : ''}`
    ).join('\n')
  : 'No previous decisions yet — use your best judgement.';

const systemPrompt = `You are a POD (Print-on-Demand) product strategist for the US apparel market.
You evaluate search trends and decide if a keyword is a good niche for POD t-shirts, hoodies, mugs, and accessories.

Scoring rubric:
- 1-3: Poor fit (too niche, already saturated, or low commercial appeal)
- 4-6: Decent (some potential, worth monitoring)
- 7-8: Good (rising trend, sellable designs possible)
- 9-10: Excellent (seasonal spike + broad appeal + design potential)

Past human decisions for context (use to calibrate your score):
${fewShot}

Respond ONLY with valid JSON in this exact format:
{"score": 7, "reasoning": "...", "llm_approved": true, "pod_suitability": "high", "peak_timing": "..."}`;

const userPrompt = `Keyword: "${trendItem.keyword}"
Event: ${trendItem.event_name || 'None'}
Type: ${trendItem.type}
Search interest (0-100): 7d=${trendItem.interest_score_7d}, 3mo=${trendItem.interest_score_3m}, 1yr=${trendItem.interest_score_1yr}
Rising queries: ${trendItem.rising_queries || 'none'}\n\nScore this keyword for POD potential.`;

return [{
  json: {
    ...trendItem,
    ollama_messages: [
      {role: 'system', content: systemPrompt},
      {role: 'user', content: userPrompt}
    ]
  }
}];

// Parse Ollama JSON response
const trendItem = $('Code: Build Ollama Prompt').item.json;
const rawText = $input.item.json?.message?.content || $input.item.json?.response || '';

let parsed = { score: 5, reasoning: 'Parse error', llm_approved: false, pod_suitability: 'unknown', peak_timing: 'unknown' };
try {
  // Extract JSON from response (Ollama sometimes wraps it)
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch(e) { parsed.reasoning = rawText.slice(0, 300); }

return [{
  json: {
    keyword: trendItem.keyword,
    event_name: trendItem.event_name || '',
    type: trendItem.type,
    locale: 'US',
    interest_score_7d: trendItem.interest_score_7d,
    interest_score_3m: trendItem.interest_score_3m,
    interest_score_1yr: trendItem.interest_score_1yr,
    rising_queries: trendItem.rising_queries || '',
    applicable_brands: trendItem.applicable_brands || [],
    llm_score: parsed.score || 5,
    llm_reasoning: parsed.reasoning || '',
    llm_approved: parsed.llm_approved || (parsed.score >= 7),
    human_approved: null,
    run_date: trendItem.run_date,
    // Sheet-friendly
    applicable_brands_str: (trendItem.applicable_brands || []).join(', '),
    status: 'Awaiting Your Review'
  }
}];
